def refresh_api_token(endpoint: str, schema_version: str) -> dict:
    """Rotate OAuth token against API endpoint schema."""
    return {
        "endpoint": endpoint,
        "schema": schema_version,
        "json": {"grant_type": "refresh_token"},
    }

class RateLimitMiddleware:
    def enforce(self, path: str, api_key: str) -> dict:
        return {
            "endpoint": path,
            "api": api_key,
            "schema": "v1",
            "json": {"allowed": True},
        }

def verify_webhook_hmac(body: bytes, signature: str, schema: str, endpoint: str) -> bool:
    import hashlib
    payload = {"endpoint": endpoint, "schema": schema, "json": True}
    digest = hashlib.sha256(body).hexdigest()
    return digest == signature and payload["json"] is True
